"""A dedicated marketing page: concrete disciplines, deliverables and enquiry paths."""
from urllib.parse import quote
from agency import art

SERVICES=[
 ('marke','01','Marke & Corporate Design','Ein Auftritt, an dem man Ihr Unternehmen wiedererkennt.','Wir übersetzen Ihre Positionierung in eine visuelle Identität. Sie erhalten Gestaltung, die auf der Website, in Social Media und auf gedruckten Materialien zusammenpasst.', ['Logoentwicklung und Logo-Überarbeitung','Farben, Typografie und Bildsprache','Corporate Design und kompakte Markenrichtlinien','Vorlagen für Präsentationen und Geschäftsausstattung'],'Logo, Gestaltungssystem und die vereinbarten Dateien für Ihre Anwendungen.','Markenauftritt entwickeln',None),
 ('kampagnen','02','Online-Marketing & Kampagnen','Aus einer Botschaft wird ein klarer Weg zur Anfrage.','Wir planen Kampagnen entlang Ihrer Zielgruppe, Ihres Angebots und des verfügbaren Budgets. Anzeigen, Inhalte und Landingpages werden gemeinsam betrachtet.', ['Marketingstrategie und Kampagnenkonzept','Google Ads und Werbung auf Meta-Plattformen','Landingpages und nachvollziehbare Kontaktwege','Auswertung und laufende Anpassung nach Vereinbarung'],'Abgestimmtes Konzept, Werbemittel und ein Plan für Umsetzung und Auswertung.','Kampagne planen',None),
 ('seo','03','SEO & lokale Sichtbarkeit','Gefunden werden, wenn Menschen nach Ihrem Angebot suchen.','Suchmaschinenoptimierung verbindet eine zugängliche Website mit hilfreichen Inhalten. Wir prüfen die technische Grundlage, die Suchabsicht Ihrer Kunden und Ihre lokalen Angaben.', ['Technisches SEO, Seitenstruktur und Indexierbarkeit','Suchbegriffe, Seitentitel und relevante Inhalte','Interne Verlinkung und strukturierte Daten','Lokale Suche und Google-Unternehmensprofil'],'Priorisierte Maßnahmen und die vereinbarten technischen und redaktionellen Anpassungen.','SEO-Projekt besprechen','suchmaschinenoptimierung.html'),
 ('lokal','04','Lokale Einträge & Unternehmensprofile','Damit Kunden den Weg zu Ihrem Unternehmen finden.','Wir richten relevante Unternehmensprofile ein und überarbeiten vorhandene Einträge. Website, Standort, Kontaktdaten und Öffnungszeiten werden aufeinander abgestimmt.', ['Google-Unternehmensprofil und Google Maps','Apple Maps und Unternehmensprofile','Bing Places und passende Branchenverzeichnisse','Profilinhalte, Bilder, Öffnungszeiten und laufende Pflege'],'Abgestimmte Profile, dokumentierte Zugänge und ein klarer Umfang für die Pflege.','Lokale Einträge besprechen','suchmaschinenoptimierung.html#lokale-eintraege'),
 ('social','04','Social Media & Content','Inhalte, die zu Ihrer Marke und Ihrem Publikum passen.','Wir entwickeln eine nachvollziehbare Kanal- und Redaktionsplanung. Gestaltung, Texte und kurze Videos werden auf die jeweilige Plattform zugeschnitten und vor der Veröffentlichung abgestimmt.', ['Instagram, Facebook, LinkedIn und TikTok nach Bedarf','Redaktionsplan, Beiträge, Stories und Reels','Texte, Bildkonzepte und wiederverwendbare Vorlagen','Freigaben, Auswertung und laufende Betreuung'],'Ein abgestimmter Redaktionsplan und veröffentlichungsfertige Inhalte im vereinbarten Umfang.','Social Media planen','social-media.html'),
 ('print','05','Printdesign & Werbemittel','Ihre Marke gehört auch in die Hand Ihrer Kunden.','Vom ersten Kontakt bis zum Verkaufsgespräch: Wir gestalten gedruckte Materialien mit einer klaren Botschaft und passenden Formaten. Druckdaten und Produktionsanforderungen werden vorab geklärt.', ['Visitenkarten, Briefpapier und Geschäftsausstattung','Flyer, Faltblätter und Broschüren','Plakate, Roll-ups und Veranstaltungsmaterial','Speisekarten, Angebotsunterlagen und Druckvorbereitung'],'Gestaltete Materialien, vereinbarte Dateiformate und druckfähige Daten.','Printmaterial gestalten',None),
 ('web','06','Websites, Landingpages & visuelle Inhalte','Der digitale Ort, an dem alles zusammenkommt.','Wir bringen Botschaft, Gestaltung und Kontakt auf Ihrer Website zusammen. Foto, Video und weitere Inhalte unterstützen die Erklärung Ihres Angebots; die technische Entwicklung ergänzt unser Bereich Technology.', ['Struktur, Texte und Design für Websites und Landingpages','Bildkonzepte, Fotografie und Video nach Projektumfang','Mobile Gestaltung und verständliche Kontaktwege','Technische Umsetzung und vereinbarte Website-Pflege'],'Ein abgestimmter Webauftritt oder einzelne Inhalte für Ihre vorhandenen Kanäle.','Websiteprojekt besprechen','webdesign.html'),
]

def formats():
 from detail_art import scene
 from detail_catalog import PAGES
 variants=[('card','Visitenkarten'),('flyer','Flyer & Print'),('social','Social Media')]
 buttons=''.join(f'<button type="button" data-format-choice="{key}" aria-pressed="{str(i==0).lower()}" aria-controls="format-{key}">{name}</button>' for i,(key,name) in enumerate(variants))
 panels=''.join(f'<div id="format-{key}" data-detail-static-scene data-format-panel="{key}"{(" hidden" if i else "")}>{scene(dict(PAGES["online-marketing.html"],kind={"card":"brand","flyer":"print","social":"social"}[key]))}</div>' for i,(key,name) in enumerate(variants))
 return f'<section class="marketing-formats" data-format-viewer><div class="shell marketing-formats-grid"><div><p class="v-kicker">EINE MARKE. PASSENDE FORMATE.</p><h2>Auf dem Bildschirm.<br>Und auf Papier.</h2><p>Eine Visitenkarte braucht andere Schwerpunkte als ein Flyer oder ein Social-Media-Beitrag. Ihre Marke bleibt dabei wiedererkennbar.</p><div class="format-options" role="group" aria-label="Gestaltungsformat auswählen">{buttons}</div><p class="format-note">Gestaltungsbeispiele mit der eigenen Marke Tafolli &amp; Co.</p><a class="lnk" href="kontakt.html?thema=marketing#projektanfrage">Ihre Materialien gestalten lassen ↗</a></div><div class="format-stage">{panels}</div></div></section>'

def page():
 from bausteine import seite_rahmen
 chapters=''
 for index,(slug,n,title,headline,text,items,result,cta,detail) in enumerate(SERVICES,1):
  n=f'{index:02}'
  detail_link=f'<a class="mk-detail" href="{detail}">Leistung im Detail →</a>' if detail else ''
  chapters+=f'''<article class="mk-chapter" id="{slug}"><div class="mk-chapter-title"><span>{n}</span><h3>{title}</h3><p>{headline}</p></div><div class="mk-chapter-content"><p>{text}</p><ul>{''.join('<li>'+item+'</li>' for item in items)}</ul><div class="mk-delivery"><small>DAS NEHMEN SIE MIT</small><p>{result}</p></div><div class="mk-chapter-actions"><a href="kontakt.html?thema=marketing&amp;leistung={quote(title)}#projektanfrage">{cta} ↗</a>{detail_link}</div></div></article>'''
 nav=''.join(f'<a href="#{s[0]}">{s[2]}</a>' for s in SERVICES)
 body=f'''<div class="marketing-page" data-specialized-page><section class="mk-hero"><div class="shell mk-hero-grid"><div><p class="v-kicker">MARKETING / TAFOLLI &amp; CO.</p><h1>Ihre Marke.<br>Überall klar<br>erkennbar.</h1><p>Strategie, Logos, Websites, SEO, Social Media und gedruckte Werbemittel. Wir gestalten Ihren Auftritt und setzen die Maßnahmen um, die zu Ihrem Unternehmen passen.</p><div class="mk-hero-actions"><a class="btn btn-1" href="kontakt.html?thema=marketing#projektanfrage">Marketingprojekt anfragen ↗</a><a class="mk-secondary" href="#marketing-leistungen">Leistungen entdecken ↓</a></div></div><div class="mk-hero-art">{art('marketing')}</div></div><nav class="shell mk-navigation" aria-label="Marketingbereiche">{nav}</nav></section>
<section class="mk-services" id="marketing-leistungen"><div class="shell"><div class="visual-section-heading"><div><p class="v-kicker">UNSER MARKETINGANGEBOT</p><h2>Was Sie brauchen.<br>Was wir liefern.</h2></div><p>Sie können eine einzelne Leistung beauftragen oder mehrere Maßnahmen verbinden. Umfang, Zuständigkeiten und Kosten werden vor dem Start abgestimmt.</p></div>{chapters}</div></section>
{formats()}
<section class="mk-engagement"><div class="shell"><div class="visual-section-heading"><div><p class="v-kicker">SO KANN DIE ZUSAMMENARBEIT BEGINNEN</p><h2>Ein konkreter Auftrag.<br>Oder laufende Begleitung.</h2></div><p>Der Einstieg richtet sich nach Ihrer Ausgangslage. Sie müssen nicht alle Marketingbereiche auf einmal beauftragen.</p></div><div class="mk-engagement-grid"><article><span>01 / EINZELPROJEKT</span><h3>Etwas Bestimmtes umsetzen.</h3><p>Zum Beispiel ein neues Logo, Visitenkarten, ein Flyer, eine Landingpage oder eine Kampagne. Mit einem klar abgegrenzten Ergebnis.</p><a href="kontakt.html?thema=marketing#projektanfrage">Einzelprojekt anfragen ↗</a></article><article><span>02 / LAUFENDE BETREUUNG</span><h3>Kontinuierlich präsent bleiben.</h3><p>Zum Beispiel mit laufender Content-Erstellung, Social Media, Anzeigen oder Website-Pflege. Umfang, Freigaben und Abstimmungen werden fest vereinbart.</p><a href="kontakt.html?thema=marketing#projektanfrage">Betreuung besprechen ↗</a></article></div></div></section>
<section class="mk-faq"><div class="shell"><p class="v-kicker">VOR DER ZUSAMMENARBEIT</p><h2>Noch eine Frage?</h2><div><details><summary>Können wir nur ein Logo oder einen Flyer beauftragen?<span>+</span></summary><p>Ja. Ein einzelnes Gestaltungsvorhaben ist ebenso möglich wie ein umfassender Markenauftritt. Im Angebot wird festgelegt, welche Entwürfe, Abstimmungen und Dateien enthalten sind.</p></details><details><summary>Können bestehende Farben, Logos und Inhalte genutzt werden?<span>+</span></summary><p>Ja. Wir prüfen Ihre vorhandenen Grundlagen und klären, was erhalten, angepasst oder ergänzt werden soll. Ein vollständiger Neustart ist nicht für jedes Projekt notwendig.</p></details><details><summary>Was kostet ein Marketingprojekt?<span>+</span></summary><p>Das hängt von den benötigten Leistungen, Formaten und der laufenden Betreuung ab. Nach der Abstimmung Ihrer Aufgabe erhalten Sie ein Angebot mit dem konkreten Leistungsumfang und den Kosten.</p></details><details><summary>Übernehmen Sie auch Druck und Werbebudget?<span>+</span></summary><p>Druckvorbereitung und Abstimmung mit einer Druckerei können vereinbart werden. Produktionskosten und Mediabudgets werden separat ausgewiesen und vor einer Beauftragung abgestimmt.</p></details></div></div></section>
<section class="mk-closing"><div class="shell"><p class="v-kicker">DER NÄCHSTE SCHRITT</p><h2>Was soll Ihre Marke<br>als Nächstes zeigen?</h2><p>Erzählen Sie uns, was Sie anbieten, wen Sie erreichen möchten und welche Materialien oder Kanäle Sie brauchen.</p><a class="btn btn-1" href="kontakt.html?thema=marketing#projektanfrage">Marketingprojekt besprechen ↗</a><a class="mk-email" href="index.html#budgetplaner">Budget und Kundenpotenzial durchspielen ↗</a><a class="mk-email" href="mailto:info@tafolli.net">info@tafolli.net</a></div></section></div>'''
 return seite_rahmen('leistungen.html','Marketing, SEO, Social Media & Design · Tafolli & Co.','Marketing von Tafolli & Co.: Logos, Corporate Design, SEO, Social Media, Kampagnen, Websites, Visitenkarten und Flyer. Besprechen Sie Ihr Projekt.','online-marketing.html',body)
